F=G.copy()
maps=[lambda i,j:(j,i),lambda i,j:(31-i,j),lambda i,j:(i,31-j),
      lambda i,j:(31-i,31-j),lambda i,j:(31-j,i),lambda i,j:(j,31-i),
      lambda i,j:(31-j,31-i),lambda i,j:(j,31-i)]
def orbit(i,j):
    o=set()
    stack=[(i,j)]
    while stack:
        a,b=stack.pop()
        if (a,b) in o: continue
        o.add((a,b))
        for m in maps:
            x,y=m(a,b)
            if 0<=x<n and 0<=y<n and (x,y) not in o: stack.append((x,y))
    return o
